begin;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values('10000000-0000-4000-8000-000000000301','refresh-client@example.test');
insert into agencies(id,name) values('aaaaaaaa-0000-4000-8000-000000000301','Refresh A');
insert into clients(id,agency_id,name) values('11111111-0000-4000-8000-000000000301','aaaaaaaa-0000-4000-8000-000000000301','Refresh A');
insert into client_users(agency_id,client_id,user_id) values('aaaaaaaa-0000-4000-8000-000000000301','11111111-0000-4000-8000-000000000301','10000000-0000-4000-8000-000000000301');
insert into integrations(id,agency_id,provider,connection_status) values('30000000-0000-4000-8000-000000000301','aaaaaaaa-0000-4000-8000-000000000301','meta','connected');
insert into meta_connections(id,agency_id,integration_id,client_id,connected_at) values('40000000-0000-4000-8000-000000000301','aaaaaaaa-0000-4000-8000-000000000301','30000000-0000-4000-8000-000000000301','11111111-0000-4000-8000-000000000301',now());
insert into meta_ad_accounts(id,agency_id,meta_connection_id,external_id,name,currency,timezone_name,business_id) values('50000000-0000-4000-8000-000000000301','aaaaaaaa-0000-4000-8000-000000000301','40000000-0000-4000-8000-000000000301','act_301','Refresh A','BRL','America/Sao_Paulo','100301');
insert into client_ad_accounts(agency_id,client_id,ad_account_id) values('aaaaaaaa-0000-4000-8000-000000000301','11111111-0000-4000-8000-000000000301','50000000-0000-4000-8000-000000000301');
create temporary view refresh_test as select request_meta_collection_refresh('11111111-0000-4000-8000-000000000301','40000000-0000-4000-8000-000000000301','2026-10-01','2026-10-03','v24.0',3,'[{"externalAccountId":"act_301","level":"account"},{"externalAccountId":"act_301","level":"campaign"}]') as result;
grant select on refresh_test to service_role;
set local role service_role;
select is((select result->>'created' from refresh_test),'2','Solicitação cria todos os escopos');
select is((select result->>'preserved' from refresh_test),'2','Repetição preserva jobs na fila');
update integration_collection_jobs set status=case when entity_level='account' then 'confirmed' else 'failed' end,attempt_count=8,completed_at=now();
insert into integration_snapshots(job_id,attempt_count,client_id,provider,external_account_id,date_from,date_to,entity_level,status,payload,collected_at)
select id,8,client_id,provider,external_account_id,date_from,date_to,entity_level,'confirmed','{"metrics":[]}',now()-interval '2 hours'
from integration_collection_jobs where entity_level='account';
select is((select result->>'rescheduled' from refresh_test),'2','Atualização recupera jobs confirmados e falhos');
select is((select min(attempt_count) from integration_collection_jobs),8,'Atualização conserva fencing monotônico');
select is((select min(retry_epoch_attempt) from integration_collection_jobs),8,'Novo ciclo reinicia orçamento de retries');
select is((select count(*) from integration_snapshots),1::bigint,'Atualização preserva snapshot anterior');
update integration_collection_jobs set priority=0 where entity_level='account';
insert into integration_collection_jobs(client_id,connection_id,provider,external_account_id,date_from,date_to,entity_level,api_version,contract_version,idempotency_key,priority)
values('11111111-0000-4000-8000-000000000301','40000000-0000-4000-8000-000000000301','google','other-account','2026-10-01','2026-10-03','campaign','v-test',1,'other-provider-job',-1);
create temporary table refresh_claim as select * from claim_meta_collection_job();
select is((select provider from refresh_claim),'meta','Executor Meta ignora outro provedor com prioridade maior');
select is((select status from integration_collection_jobs where provider='google'),'queued','Claim Meta conserva fila de outro provedor');
select is((select attempt_count from refresh_claim),9,'Novo claim incrementa tentativa vitalícia');
select is((select retry_attempt_count from refresh_claim),1,'Primeiro retry do ciclo é um');
select is((select result->>'preserved' from refresh_test),'2','Nova solicitação não interrompe claim nem job na fila');
select throws_ok($q$select finish_integration_collection_job((select job_id from refresh_claim),8,'confirmed')$q$,'40001',null,'Worker anterior não finaliza ciclo novo');
select finish_integration_collection_job((select job_id from refresh_claim),9,'partial',now());
select is((select result->>'preserved' from refresh_test),'2','Solicitação preserva retry parcial e seu backoff');
update integration_collection_jobs set priority=200 where id<>(select job_id from refresh_claim);
create temporary table refresh_second_claim as select * from claim_meta_collection_job();
select is((select attempt_count from refresh_second_claim),10,'Retry mantém fencing crescente');
select is((select retry_attempt_count from refresh_second_claim),2,'Retry conta apenas ciclo atual');
select finish_integration_collection_job((select job_id from refresh_second_claim),10,'failed');
select throws_ok($q$select request_meta_collection_refresh('11111111-0000-4000-8000-000000000301','40000000-0000-4000-8000-000000000301','2026-10-01','2026-10-03','v24.0',3,'[{"externalAccountId":"act_301","level":"account"},{"externalAccountId":"act_999","level":"campaign"}]')$q$,'42501',null,'Conta sem autorização desfaz solicitação inteira');
select is((select count(*) from integration_collection_jobs where status='failed'),1::bigint,'Falha transacional conserva job terminal');
select throws_ok($q$select request_meta_collection_refresh('11111111-0000-4000-8000-000000000301','40000000-0000-4000-8000-000000000301','2026-10-01','2026-10-03','v24.0',3,'[]')$q$,'22023',null,'Lista vazia é rejeitada');
select throws_ok($q$select request_meta_collection_refresh('11111111-0000-4000-8000-000000000301','40000000-0000-4000-8000-000000000301','2026-10-01','2026-10-03','v24.0',3,'[{"externalAccountId":"act_301","level":"ad"},{"externalAccountId":"act_301","level":"ad"}]')$q$,'22023',null,'Escopo duplicado é rejeitado atomicamente');
select is((select count(*) from integration_collection_jobs where entity_level='ad'),0::bigint,'Duplicata não deixa job parcial');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000301',true);
select ok(get_confirmed_collection_snapshot('11111111-0000-4000-8000-000000000301','40000000-0000-4000-8000-000000000301','meta','act_301','2026-10-01','2026-10-03','account','v24.0',3) is not null,'Cliente ainda lê confirmado durante atualização/falha posterior');
select throws_ok($q$select request_meta_collection_refresh('11111111-0000-4000-8000-000000000301','40000000-0000-4000-8000-000000000301','2026-10-01','2026-10-03','v24.0',3,'[{"externalAccountId":"act_301","level":"account"}]')$q$,'42501',null,'Sessão de cliente não chama RPC de serviço');
reset role;
update client_ad_accounts set active=false;
set local role service_role;
select throws_ok($q$select * from refresh_test$q$,'42501',null,'Conta revogada impede nova coleta');
reset role;
select ok(not has_function_privilege('anon','public.request_meta_collection_refresh(uuid,uuid,date,date,text,integer,jsonb)','execute'),'Visitante não solicita refresh');
select ok(not has_function_privilege('authenticated','public.claim_meta_collection_job(timestamptz)','execute'),'Sessão autenticada não reivindica jobs Meta');
select * from finish();
rollback;
